referenceSolutions.javascript:
export function firstMissingPositive(values          )         {
const a=[...values];for(let i=0;i<a.length;i++)while(a[i]>0&&a[i]<=a.length&&a[a[i]-1]!==a[i]){const j=a[i]-1;[a[i],a[j]]=[a[j],a[i]];}for(let i=0;i<a.length;i++)if(a[i]!==i+1)return i+1;return a.length+1;
}

